// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Reason', price: 1000000 },
  { id: '2', name: 'Snow Crash', price: 24.99 }
];

const renderCheckout = (items = mockCartItems) => {
  return render(
    <CartProvider value={{ items, total: 1000024.99, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Complete Targeting Sequence', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-742' });
  });

  // Happy Path - Full Payload Delivery
  it('completes checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    renderCheckout();

    // Shipping phase
    await user.type(screen.getByLabelText(/street address/i), '1 Raft City');
    await user.type(screen.getByLabelText(/city/i), 'Pacific Ocean');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment phase
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Hiro Protagonist');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review phase
    expect(screen.getByText(/ending in 1111/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-742');
    });
  });

  // Validation - Defensive Countermeasures
  it('displays validation errors for empty shipping fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
  });

  it('validates ZIP code format with precision', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  // Empty Cart - Target Absent
  it('displays empty cart message when no items present', () => {
    renderCheckout([]);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // Payment Failure - Countermeasure Deployed
  it('displays error and allows retry on payment failure', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    // ...proceed to review step
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });

  // Loading State - Systems Engaged
  it('disables buttons and shows loading during submission', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {}));
    // ...proceed to review
    await userEvent.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });

  // Accessibility - Geneva Convention Compliance
  it('marks invalid fields with aria-invalid', async () => {
    renderCheckout();
    await userEvent.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });
});
